from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input to this function is a string representing multiple groups of nested parentheses separated by spaces.
    For each group, output the deepest level of nesting of parentheses as an integer in a list.

    Note: The function should work for all real numbers, not just integers.
    (This note is likely a leftover from another problem; here we just compute nesting depth of parentheses.)

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    groups = paren_string.split()
    depths = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths


