from typing import List, Tuple, Union

def parse_music(music_string: str) -> Union[List[int], Tuple[List[int], str]]:
    if not music_string.strip():
        return []
    note_to_beats = {'o': 4, 'o|': 2, '.|': 1}
    notes = music_string.split()
    beats_list = []
    count_map = {}
    total_beats_map = {}
    for note in notes:
        beats = note_to_beats.get(note, 0)
        beats_list.append(beats)
        count_map[note] = count_map.get(note, 0) + 1
        total_beats_map[note] = total_beats_map.get(note, 0) + beats
    max_count = max(count_map.values())
    candidates = [n for n, c in count_map.items() if c == max_count]
    most_common_note = max(candidates, key=lambda n: total_beats_map[n])
    return (beats_list, most_common_note)


