def fizz_buzz(n: int) -> int:
    """Return the count of digit '7' appearances in the concatenated string representations
    of all numbers less than n that are divisible by 11 or 13.

    Examples:
    >>> fizz_buzz(50)
    0
    >>> fizz_buzz(78)
    2
    >>> fizz_buzz(79)
    3
    """
    numbers = (str(i) for i in range(n) if i % 11 == 0 or i % 13 == 0)
    concatenated = ''.join(numbers)
    return concatenated.count('7')


