def triples_sum_to_zero(l: list):
    """
    triples_sum_to_zero takes a list of integers or strings representing integers as input.
    It returns True if there are three distinct elements in the list that sum to zero,
    and False otherwise. The original list is not modified.

    The function internally converts all elements to integers and uses a sorted copy 
    of the list for the sum search.

    >>> triples_sum_to_zero([1, 3, 5, 0])
    True
    >>> triples_sum_to_zero([1, 3, -2, 1])
    True
    >>> triples_sum_to_zero([1, 2, 3, 7])
    False
    >>> triples_sum_to_zero([2, 4, -5, 3, 9, 7])
    True
    >>> triples_sum_to_zero([1])
    False
    >>> triples_sum_to_zero(['1', '3', '-2', '1'])
    True
    """
    arr = [int(x) for x in l]
    arr_sorted = sorted(arr)
    n = len(arr_sorted)
    for i in range(n - 2):
        left, right = (i + 1, n - 1)
        while left < right:
            s = arr_sorted[i] + arr_sorted[left] + arr_sorted[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


