def monotonic(l):

    def has_duplicates(seq, seen=()):
        if not seq:
            return False
        if seq[0] in seen:
            return True
        return has_duplicates(seq[1:], seen + (seq[0],))

    def non_decreasing(seq):
        if len(seq) < 2:
            return True
        return seq[0] <= seq[1] and non_decreasing(seq[1:])

    def non_increasing(seq):
        if len(seq) < 2:
            return True
        return seq[0] >= seq[1] and non_increasing(seq[1:])
    if isinstance(l, str):
        if has_duplicates(l):
            return False
        if non_decreasing(l) or non_increasing(l):
            return (True, l)
        return False
    if not l or len(l) == 1:
        return True
    if non_decreasing(l) or non_increasing(l):
        return True
    return False


