def total_match(lst1, lst2):
    """
    Craft a function that takes in two lists of integers and returns the list that has 
    total number of digits in all the numbers of the list less than the other list.

    Additionally, if the two lists have the same number of digits, return the first list.

    However, the function must also be able to handle strings and should return the longest string in case it encounters one.

    The function should return the result as a string.

    Lastly, the order of the output list must be in ascending order but at the same time maintain its original order.

    Examples
    total_match([], []) ➞ []
    total_match([12, 345], [123, 45]) ➞ "123 45"
    total_match([12, 345], [12, 12, 345, 789]) ➞ "12 345"
    total_match([12, 345], [123, 12, 12]) ➞ "123 12 12"
    total_match([4], [1, 2, 3, 4, 5]) ➞ "4"
    total_match(['hi', 'admin'], ['hI', 'Hi']) ➞ 'admin'
    """

    def contains_string(lst):
        return any((isinstance(x, str) for x in lst))
    if contains_string(lst1) or contains_string(lst2):
        combined = lst1 + lst2
        strings = [x for x in combined if isinstance(x, str)]
        if not strings:
            return ''
        longest = max(strings, key=len)
        return longest

    def total_digits(lst):
        total = 0
        for n in lst:
            s = str(n)
            s = s.lstrip('-+')
            s = s.replace('.', '')
            total += len(s)
        return total
    total1 = total_digits(lst1)
    total2 = total_digits(lst2)
    chosen = lst1 if total1 <= total2 else lst2
    sorted_chosen = sorted(chosen, key=lambda x: x)
    return ' '.join((str(x) for x in sorted_chosen))


