def count_upper(s):
    """
    Given a string s, count the number of uppercase vowels in even indices,
    but return the result as an integer count.

    The function is case-insensitive and considers all characters as lowercase
    for the purpose of identifying vowels, but only counts vowels that are
    uppercase in the original string at even indices.

    Examples:
    count_upper('aBCdEf') returns 1
    count_upper('abcdefg') returns 0
    count_upper('dBBE') returns 0
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}
    count = 0
    for i in range(0, len(s), 2):
        c = s[i]
        if c.isupper() and c.lower() in vowels:
            count += 1
    return count


