def maximum(arr, k):
    """
    Given an array arr of integers or strings and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr sorted in ascending order.

    Constraints:
        - No built-in sorting function can be used.
    """
    if k == 0:
        return []
    arr_copy = list(arr)
    largest = []
    for _ in range(k):
        max_elem = arr_copy[0]
        for x in arr_copy[1:]:
            if x > max_elem:
                max_elem = x
        largest.append(max_elem)
        for i in range(len(arr_copy)):
            if arr_copy[i] == max_elem:
                arr_copy.pop(i)
                break
    for i in range(1, k):
        key = largest[i]
        j = i - 1
        while j >= 0 and largest[j] > key:
            largest[j + 1] = largest[j]
            j -= 1
        largest[j + 1] = key
    return largest


