def order_by_points(nums):
    """
    Sorts the given list of integers or strings representing integers in ascending order
    according to the sum of their digits, where the negative sign applies only to the first digit.
    If sums tie, original order is preserved. Returns a list of the original values sorted accordingly.
    No loops or recursion are used.
    """

    def digit_sum(x):
        s = str(x)
        if not s:
            return 0
        neg = s[0] == '-'
        digits = s[1:] if neg else s
        if not digits:
            return 0
        first_digit = int(digits[0])
        rest_sum = sum(map(int, digits[1:])) if len(digits) > 1 else 0
        return (-first_digit if neg else first_digit) + rest_sum
    indexed = list(enumerate(nums))
    sorted_indexed = sorted(indexed, key=lambda iv: (digit_sum(iv[1]), iv[0]))
    return [iv[1] for iv in sorted_indexed]


