from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given a string containing groups of parentheses separated by space characters,
    for each group return the maximum nesting depth of parentheses in that group.
    Non-parenthesis characters inside a group are ignored for nesting depth calculation
    but do not split groups.
    """
    groups = paren_string.split(' ')
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                if current_depth > 0:
                    current_depth -= 1
        result.append(max_depth)
    return result


