def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return the digits reversed as a string.

    The negative sign is preserved if x is negative.

    >>> circular_shift(12, 1)
    '21'
    >>> circular_shift(12, 2)
    '12'
    >>> circular_shift(12, 3)
    '21'
    >>> circular_shift(-123, 1)
    '-312'
    >>> circular_shift(-123, 4)
    '-321'
    """
    s = str(x)
    sign = ''
    if s.startswith('-'):
        sign = '-'
        s = s[1:]
    n = len(s)
    if n == 0:
        return sign
    if shift > n:
        return sign + s[::-1]
    shift = shift % n
    if shift == 0:
        return sign + s
    return sign + s[-shift:] + s[:-shift]


