def select_words(s, n):
    """Given a string s and a natural number n, return a list of all words from s 
    that contain exactly n consonants, in order they appear in s.
    If s is empty, return an empty list.
    Assumes s contains only letters and spaces.
    """
    vowels = set('aeiouAEIOU')
    result = []
    for word in s.split():
        consonant_count = sum((1 for ch in word if ch.isalpha() and ch not in vowels))
        if consonant_count == n:
            result.append(word)
    return result


