def sum_squares(lst):
    """
    This function will take a list of integers. The function shall then return the sum of all entries 
    transformed as follows:
      - if the element's zero-based index is a multiple of 3, square the element
      - else if the index is a multiple of 4, cube the element
      - else leave the element unchanged
    Then sum all transformed values and return the sum as an integer.

    Examples:
    For lst = [1,2,3] the output should be 14
    For lst = [] the output should be 0
    For lst = [-1,-5,2,-1,-5] the output should be 4
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total


