def triples_sum_to_zero(l):
    """
    Returns True if there exist three distinct elements in the list l whose sum is zero.
    Otherwise, returns False.
    """
    n = len(l)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if l[i] + l[j] + l[k] == 0:
                    return True
    return False


