def monotonic(l: list):
    """Return True if list elements are entirely non-decreasing or non-increasing.

    >>> candidate([1, 2, 4, 20])
    True
    >>> candidate([1, 20, 4, 10])
    False
    >>> candidate([4, 1, 0, -10])
    True
    """
    if len(l) <= 1:
        return True
    non_decreasing = all((x <= y for x, y in zip(l, l[1:])))
    non_increasing = all((x >= y for x, y in zip(l, l[1:])))
    return non_decreasing or non_increasing


