def digits(n):
    """Given a positive integer n, return the product of the odd digits if there are multiple,
    the single odd digit if only one odd digit exists, or 0 if all digits are even.
    """
    odd_digits = [int(d) for d in str(int(n)) if int(d) % 2 == 1]
    if not odd_digits:
        return 0
    product = 1
    for d in odd_digits:
        product *= d
    return product


