def solve(s):
    has_letter = any((c.isalpha() for c in s))
    if has_letter:
        changed = []
        for c in s:
            if isinstance(c, str) and c.isalpha():
                if c.islower():
                    changed.append(c.upper())
                else:
                    changed.append(c.lower())
            else:
                changed.append(c)
        if isinstance(s, str):
            return ''.join(changed)
        elif isinstance(s, tuple):
            return tuple(changed)
        elif isinstance(s, list):
            return changed
        else:
            try:
                return type(s)(changed)
            except Exception:
                return changed
    elif isinstance(s, str):
        return s[::-1]
    elif isinstance(s, tuple):
        return s[::-1]
    elif isinstance(s, list):
        return s[::-1]
    else:
        try:
            return type(s)(s[::-1])
        except Exception:
            return list(s)[::-1]


