def triples_sum_to_zero(items):
    """
    Returns True if there exist three distinct entries in items that sum to zero,
    False otherwise.
    """
    n = len(items)
    if n < 3:
        return False
    items = list(items)
    items.sort()
    for i in range(n - 2):
        if i > 0 and items[i] == items[i - 1]:
            continue
        left, right = (i + 1, n - 1)
        while left < right:
            total = items[i] + items[left] + items[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False


