def decode_shift(data):
    """
    Accepts a string produced by encode_shift (which shifts each lowercase letter 5 places forward,
    wrapping around a-z), and returns the original string by shifting each lowercase letter 5 places backward.
    Characters outside a-z are left unchanged.
    """
    result = []
    for c in data:
        if 'a' <= c <= 'z':
            shifted = chr((ord(c) - ord('a') - 5) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(c)
    return ''.join(result)


