def monotonic(seq):
    """Return True if sequence items broadly move in one direction.
    >>> trend([1, 2, 4, 20])
    True
    >>> trend([1, 20, 4, 10])
    False
    >>> trend([4, 1, 0, -10])
    True
    """
    if not seq:
        return True
    nondecreasing = all((x <= y for x, y in zip(seq, seq[1:])))
    nonincreasing = all((x >= y for x, y in zip(seq, seq[1:])))
    return nondecreasing or nonincreasing


