def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13.
    >>> fizz_buzz(50)
    2
    >>> fizz_buzz(78)
    4
    >>> fizz_buzz(79)
    4
    """
    count = 0
    for x in range(n):
        if x % 11 == 0 or x % 13 == 0:
            count += str(x).count('7')
    return count


