def monotonic(l: list):
    """Return True if list elements are monotonically nondecreasing or nonincreasing.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if not l or len(l) == 1:
        return True
    nondecreasing = True
    nonincreasing = True
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            nondecreasing = False
        if l[i] > l[i - 1]:
            nonincreasing = False
        if not nondecreasing and (not nonincreasing):
            return False
    return nondecreasing or nonincreasing


