def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    break_points = []
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            break_points.append(i)
    if not break_points:
        return True
    if len(break_points) > 1:
        return False
    bp = break_points[0]
    rotated = arr[bp + 1:] + arr[:bp + 1]
    for i in range(n - 1):
        if rotated[i] > rotated[i + 1]:
            return False
    return True


