def decode_shift(s):
    """
    Decodes a string encoded by shifting every lowercase character by 5 positions forward in the alphabet.
    Shifts every lowercase character backward by 5 positions, leaving other characters unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            decoded_char = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(decoded_char)
        else:
            result.append(ch)
    return ''.join(result)


