def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    >>> circular_shift(12, 1)
    "21"
    >>> circular_shift(12, 2)
    "12"
    """
    s = str(abs(int(x)))
    n = len(s)
    sign = '-' if x < 0 else ''
    if abs(shift) > n:
        return sign + s[::-1]
    shift = shift % n
    if shift == 0:
        return sign + s
    shifted = s[-shift:] + s[:-shift]
    return sign + shifted


