def will_it_fly(q, w):
    """
    Write a function that returns True if the object q will fly, and False otherwise.

    The object flies if:
    - The total weight sum(q) is less than or equal to w
    - The weight distribution q is balanced, meaning q is a palindrome

    Examples:
    will_it_fly([1, 2], 5) ➞ False 
    # sum=3 <=5 but not palindrome -> False

    will_it_fly([3, 2, 3], 1) ➞ False
    # sum=8 >1 -> False

    will_it_fly([3, 2, 3], 9) ➞ True
    # sum=8 <=9 and palindrome -> True

    will_it_fly([3], 5) ➞ True
    # sum=3 <=5 and single element (palindrome) -> True
    """
    return sum(q) <= w and q == q[::-1]


