def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k containing the k largest elements from arr including duplicates.
    If arr has fewer than k elements, return all elements sorted ascending.
    If k is zero, return an empty list.
    """
    if k == 0:
        return []
    if k >= len(arr):
        return sorted(arr)
    from heapq import nlargest
    largest_k = nlargest(k, arr)
    return sorted(largest_k)


