def sum_squares(lst):
    """
    This function will take a list of integers. The function shall then return the sum of all entries,
    but elements at indexes that are multiples of 3 or 4 are squared before summing.

    Examples:
    For lst = [1,2,3] the output should be 6
    For lst = [] the output should be 0
    For lst = [-1,-5,2,-1,-5] the output should be -126
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0 or i % 4 == 0:
            total += val ** 2
        else:
            total += val
    return total


