def parse_nested_parens(paren_string):
    """ Input to this function is a string. Output a list of deepest levels of nesting of parentheses
        for each group separated by spaces.
    """
    groups = paren_string.split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                if current_depth > 0:
                    current_depth -= 1
        result.append(max_depth)
    return result


