def circular_shift(x, shift):
    """Circular shift the digits of  x, shift the digits right by shift
    and return the result as a string, preserving leading zeros in the output.
    """
    s = str(x)
    if not s:
        return s
    n = len(s)
    if n == 0:
        return s
    shift = shift % n if n else 0
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]


