def select_words(s, n):
    """Implement a function that returns a list of all words from string s that contain exactly 
    n consonants, in order these words appear in the string s. 

    """
    import string
    vowels = set('aeiou')
    consonants = set(string.ascii_lowercase) - vowels
    result = []
    for word in s.split():
        cleaned = ''.join((ch.lower() for ch in word if ch.isalpha()))
        count_consonants = sum((ch in consonants for ch in cleaned))
        if count_consonants == n:
            result.append(word)
    return result


