def digits(n):
    """Given an integer n, return the product of the odd digits in its absolute value.
    Return 0 if no odd digits are found.
    """
    product = 1
    found_odd = False
    for d in str(abs(int(n))):
        digit = int(d)
        if digit % 2 == 1:
            product *= digit
            found_odd = True
    return product if found_odd else 0


