def monotonic(l: list):
    """Return True if the list is monotonic (entirely nondecreasing or nonincreasing), False otherwise.

    >>> candidate([1, 2, 4, 20])
    True
    >>> candidate([1, 20, 4, 10])
    False
    >>> candidate([4, 1, 0, -10])
