def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits left or right by shift
    and return the result as a string.
    If shift >= number of digits, return digits reversed.
    Positive shift means circular shift to the right.
    Negative shift means circular shift to the left.
    The sign of x is not included in the output.

    >>> circular_shift(12, 1)
    "21"
    >>> circular_shift(12, 2)
    "21"
    """
    digits = str(abs(int(x)))
    n = len(digits)
    if n == 0:
        return ''
    if abs(shift) >= n:
        return digits[::-1]
    shift = shift % n
    if shift == 0:
        return digits
    if shift > 0:
        return digits[-shift:] + digits[:-shift]
    else:
        shift = -shift
        return digits[shift:] + digits[:shift]


