def smallest_change(arr):
    """
    Given an array arr of integers (or floats), find the minimum number of elements
    that need to be changed to make the array palindromic. One change changes one element 
    to any other value.

    This counts one change per mismatched pair of elements at mirrored positions.
    """
    changes = 0
    n = len(arr)
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes


