def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length meets a certain condition (e.g. is an even or prime number or another type) or False otherwise
    Examples
    candidate('Hello') == False
    candidate('abcdcba') == False
    candidate('kittens') == False
    candidate('orange') == True
    """

    def prime_length(string):
        """Return True if the length of the string is a prime number, False otherwise."""
        n = len(string)
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True
    return prime_length(string)


