def count_upper(s):
    """
    Given a string s, count the number of uppercase vowels in even indices.

    For example:
    count_upper('aBCdEf') returns 1  # 'E' at index 4
    count_upper('abcdefg') returns 0  # no uppercase vowels
    count_upper('dBBE') returns 0  # 'E' at index 3 (odd), so count is 0 by the rule
    """
    vowels = {'A', 'E', 'I', 'O', 'U'}
    count = 0
    for i in range(0, len(s), 2):
        if s[i] in vowels:
            count += 1
    return count


