def digits(n):
    """Given a positive integer n, return the product of the odd digits.
    Return 0 if no odd digits are present.
    """
    digits_str = str(n)
    odd_digits = [int(d) for d in digits_str if int(d) % 2 == 1]
    if not odd_digits:
        return 0
    product = 1
    for d in odd_digits:
        product *= d
    return product


