def compute_Last_Digit(a, b):
    try:
        a_int = int(a)
    except:
        a_int = 0
    try:
        b_int = int(b)
    except:
        b_int = 0
    if b_int <= a_int:
        return 1
    count_5 = 0
    for x in range(a_int + 1, b_int + 1):
        if x % 5 == 0:
            count_5 += 1
    count_2 = 0
    for x in range(a_int + 1, b_int + 1):
        if x % 2 == 0:
            count_2 += 1
    if count_5 > 0 and count_2 > 0:
        return 0
    last_digit = 1
    for x in range(a_int + 1, b_int + 1):
        last_digit = last_digit * (x % 10) % 10
    return last_digit


