def get_total_number_of_sequences(m, n):
    if n == 0 or m < 1:
        return 0
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for x in range(1, m + 1):
        dp[1][x] = 1
    for i in range(2, n + 1):
        suffix_sum = [0] * (m + 2)
        for y in range(1, m + 1):
            suffix_sum[y] = suffix_sum[y - 1] + dp[i - 1][y]
        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                dp[i][x] = suffix_sum[limit]
            else:
                dp[i][x] = 0
    return sum(dp[n][1:])


