def permute_string(s):
    if len(s) <= 1:
        return [s]
    first, rest = (s[0], s[1:])
    perms_rest = permute_string(rest)
    result = []
    seen = set()
    for perm in perms_rest:
        for i in range(len(perm) + 1):
            new_perm = perm[:i] + first + perm[i:]
            if new_perm not in seen:
                seen.add(new_perm)
                result.append(new_perm)
    return result


