def find_Max(arr):
    if not arr:
        return None
    n = len(arr)
    if n == 1:
        return arr[0]
    if arr[0] < arr[-1]:
        return arr[-1]
    left, right = (0, n - 1)
    while left < right:
        mid = (left + right) // 2
        if mid < n - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if arr[mid] < arr[0]:
            right = mid - 1
        else:
            left = mid + 1
    return arr[left]


