def capital_words_spaces(s):
    if not s:
        return s
    result = []
    word_start = 0
    i = 1
    n = len(s)
    while i < n:
        if s[i].isupper():
            if s[i - 1].islower():
                result.append(s[word_start:i])
                word_start = i
            elif i + 1 < n and s[i + 1].islower():
                result.append(s[word_start:i])
                word_start = i
        i += 1
    result.append(s[word_start:])
    return ' '.join(result)


