def lucky_num(n):
    if n <= 0:
        return []
    limit = max(10, 5 * n)
    while True:
        numbers = list(range(1, limit + 1, 2))
        idx = 1
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            del numbers[step - 1::step]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        limit *= 2


