def compute_Last_Digit(a, b):
    a = int(a)
    b = int(b)
    if a == b:
        return 1
    start = min(a, b)
    end = max(a, b)
    product_last_digit = 1
    for n in range(start + 1, end + 1):
        product_last_digit = product_last_digit * (n % 10) % 10
        if product_last_digit == 0:
            break
    return product_last_digit


