def next_smallest_palindrome(num):
    """
    Returns the next strictly greater palindrome integer than num.
    """
    if not isinstance(num, int):
        try:
            num = int(num)
        except Exception:
            return None
    if num < 0:
        return 0

    def build_palindrome(left, odd_length):
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])
    candidate = num + 1
    while True:
        s = str(candidate)
        length = len(s)
        half_len = (length + 1) // 2
        left = s[:half_len]
        odd_length = length % 2 != 0
        pal = build_palindrome(left, odd_length)
        if pal >= candidate:
            return pal
        left_num = int(left) + 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            candidate = 10 ** length + 1
        else:
            candidate = build_palindrome(left_str, odd_length)


