def sort_sublists(collection):

    def sort_subseq(subseq):
        try:
            if isinstance(subseq, str):
                return subseq
            sorted_items = sorted(subseq)
            if isinstance(subseq, tuple):
                return tuple(sorted_items)
            elif isinstance(subseq, list):
                return sorted_items
            else:
                try:
                    return type(subseq)(sorted_items)
                except Exception:
                    return sorted_items
        except TypeError:
            return subseq
    try:
        sorted_collection = [sort_subseq(item) for item in collection]
        if isinstance(collection, tuple):
            return tuple(sorted_collection)
        elif isinstance(collection, list):
            return sorted_collection
        else:
            try:
                return type(collection)(sorted_collection)
            except Exception:
                return sorted_collection
    except TypeError:
        return collection


