def find_solution(a, b, n):

    def to_int_if_integral(x):
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return x
    a = to_int_if_integral(a)
    b = to_int_if_integral(b)
    n = to_int_if_integral(n)

    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - aa // bb * y1
        return (gcd, x, y)
    if a == 0 and b == 0:
        return ('x = ', 0, ', y = ', 0)
    elif a == 0:
        if b != 0 and n % b == 0:
            y = n // b
            return ('x = ', 0, ', y = ', y)
        else:
            return ('x = ', 0, ', y = ', 0)
    elif b == 0:
        if a != 0 and n % a == 0:
            x = n // a
            return ('x = ', x, ', y = ', 0)
        else:
            return ('x = ', 0, ', y = ', 0)
    gcd, x0, y0 = extended_gcd(a, b)
    if isinstance(n, int) and n % gcd == 0:
        factor = n // gcd
        x = x0 * factor
        y = y0 * factor
        return ('x = ', x, ', y = ', y)
    else:
        return ('x = ', 0, ', y = ', 0)


