def decode_list(sequence):
    result = []
    i = 0
    n = len(sequence)
    while i < n:
        if i + 1 < n and isinstance(sequence[i], (int, float)) and isinstance(sequence[i + 1], (int, float)):
            count = sequence[i]
            value = sequence[i + 1]
            try:
                repeats = int(count)
                if repeats < 0:
                    repeats = 0
            except Exception:
                repeats = 0
            result.extend([value] * repeats)
            i += 2
        else:
            result.append(sequence[i])
            i += 1
    return result


