def get_total_number_of_sequences(N, K):
    if K == 0:
        return 0
    if K == 1:
        return N
    dp = [[0] * (N + 1) for _ in range(K + 1)]
    for x in range(1, N + 1):
        dp[1][x] = 1
    for length in range(2, K + 1):
        prefix = [0] * (N + 2)
        for x in range(1, N + 1):
            prefix[x] = prefix[x - 1] + dp[length - 1][x]
        for x in range(1, N + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp[length][x] = prefix[max_prev]
            else:
                dp[length][x] = 0
    return sum(dp[K][1:])


