def remove_column(collection, position):

    def remove_from_inner(inner):
        if not isinstance(inner, (list, tuple)):
            return inner
        if 0 <= position < len(inner):
            new_inner = inner[:position] + inner[position + 1:]
        else:
            new_inner = inner
        return type(inner)(new_inner)
    if not isinstance(collection, (list, tuple)):
        return collection
    return type(collection)((remove_from_inner(inner) for inner in collection))


