def next_smallest_palindrome(n):
    n = int(n)
    if n < 8:
        return n + 1 if n < 9 else 11
    s = str(n)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (length - 1) + '1')

    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]
    odd_length = length % 2 != 0
    mid = length // 2
    if odd_length:
        left = s[:mid + 1]
    else:
        left = s[:mid]
    pal_candidate = int(make_palindrome(left, odd_length))
    if pal_candidate > n:
        return pal_candidate
    if odd_length:
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            return int(incremented + incremented[:-1][::-1])
        return int(make_palindrome(incremented, True))
    else:
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            return int(incremented + incremented[:-1][::-1])
        return int(make_palindrome(incremented, False))


