def get_total_number_of_sequences(max_value, length):
    if length == 0:
        return 0
    if length == 1:
        return max_value
    dp = [[0] * (max_value + 1) for _ in range(length + 1)]
    for v in range(1, max_value + 1):
        dp[length][v] = 1
    for pos in range(length - 1, 0, -1):
        for val in range(1, max_value + 1):
            limit = min(max_value, 2 * val)
            dp[pos][val] = sum(dp[pos + 1][1:limit + 1])
    return sum(dp[1][1:max_value + 1])


