def smallest_missing(arr, low, high):
    if low > high or low < 0 or high >= len(arr):
        return 0
    start, end = (low, high)
    base = arr[low]
    while start <= end:
        mid = (start + end) // 2
        expected = base + (mid - low)
        if arr[mid] == expected:
            start = mid + 1
        else:
            end = mid - 1
    return base + (start - low)


