def permute_string(s):
    result = []
    chars = list(s)
    n = len(chars)

    def backtrack(path, used):
        if len(path) == n:
            result.append(''.join(path))
            return
        for i in range(n):
            if used[i]:
                continue
            used[i] = True
            path.append(chars[i])
            backtrack(path, used)
            path.pop()
            used[i] = False
    backtrack([], [False] * n)
    return result


