def lucky_num(n):
    if n <= 0:
        return []
    size = max(50, n * 10)
    while True:
        numbers = list(range(1, 2 * size, 2))
        idx = 1
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            del numbers[step - 1::step]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        size *= 2


