def next_smallest_palindrome(num):
    try:
        n = int(num)
    except Exception:
        n = 0
    if n < 0:
        n = 0
    if 0 <= n < 8:
        return n + 1
    s = str(n + 1)
    length = len(s)
    half = length // 2
    odd = length % 2 != 0
    while True:
        left = s[:half]
        middle = s[half] if odd else ''
        if odd:
            palindrome = left + middle + left[::-1]
        else:
            palindrome = left + left[::-1]
        pnum = int(palindrome)
        if pnum >= int(s):
            return pnum
