def find_solution(a, b, n):
    try:
        a = int(a)
        b = int(b)
        n = int(n)
    except (ValueError, TypeError):
        return None
    if a == 0 and b == 0:
        if n == 0:
            return ('x = ', 0, ', y = ', 0)
        else:
            return None
    if a == 0:
        if b != 0 and n % b == 0 and (n // b >= 0):
            return ('x = ', 0, ', y = ', n // b)
        else:
            return None
    if b == 0:
        if a != 0 and n % a == 0 and (n // a >= 0):
            return ('x = ', n // a, ', y = ', 0)
        else:
            return None
    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
        x += 1
    return None


