def next_power_of_2(x):

    def single_next_power_of_2(n):
        if not isinstance(n, (int, float)):
            return 1
        if n <= 0:
            return 1
        from math import ceil
        m = ceil(n)
        if m & m - 1 == 0:
            return m
        return 1 << m.bit_length()
    if isinstance(x, (list, tuple)):
        return type(x)((single_next_power_of_2(i) for i in x))
    else:
        return single_next_power_of_2(x)


