def find_exponentio(base, exp):

    def is_iterable(x):
        return isinstance(x, (tuple, list))
    if not is_iterable(base) and (not is_iterable(exp)):
        return base ** exp
    base_is_iter = is_iterable(base)
    exp_is_iter = is_iterable(exp)
    if base_is_iter:
        base_vals = tuple(base)
    else:
        base_vals = (base,)
    if exp_is_iter:
        exp_vals = tuple(exp)
    else:
        exp_vals = (exp,)
    len_base = len(base_vals)
    len_exp = len(exp_vals)
    length = max(len_base, len_exp)

    def broadcast(vals, n):
        if len(vals) == n:
            return vals
        if len(vals) == 1:
            return vals * n
        if len(vals) < n:
            reps, rem = divmod(n, len(vals))
            return vals * reps + vals[:rem]
        return vals[:n]
    base_b = broadcast(base_vals, length)
    exp_b = broadcast(exp_vals, length)
    result = tuple((b ** e for b, e in zip(base_b, exp_b)))
    return result


