def get_total_number_of_sequences(m, n):
    """
    Count the number of length-n sequences of integers from 1 to m inclusive,
    that are nondecreasing and satisfy the doubling condition between consecutive elements:
    For each consecutive pair (a[i], a[i+1]), a[i+1] <= 2 * a[i].

    Parameters:
    m (int or float): The maximum integer value in the sequence (considered as integers 1 to m).
    n (int or float): The length of the sequences.

    Returns:
    int: The count of sequences satisfying the conditions.
    """
    m = int(m)
    n = int(n)
    if n <= 0 or m <= 0:
        return 0
    if n == 1:
        return m
    dp = [[0] * (m + 1) for _ in range(n)]
    for val in range(1, m + 1):
        dp[0][val] = 1
    for pos in range(1, n):
        prefix = [0] * (m + 2)
        for val in range(1, m + 1):
            prefix[val] = prefix[val - 1] + dp[pos - 1][val]
        for val in range(1, m + 1):
            low = (val + 1) // 2
            high = val
            if low <= high:
                dp[pos][val] = prefix[high] - prefix[low - 1]
            else:
                dp[pos][val] = 0
    return sum(dp[n - 1][1:m + 1])


