def text_match_two_three(text, pattern):
    if pattern == '':
        return False
    count = 0
    start = 0
    plen = len(pattern)
    while True:
        index = text.find(pattern, start)
        if index == -1:
            break
        count += 1
        start = index + plen
        if count > 3:
            return False
    return count == 2 or count == 3


