def permute_string(s):

    def backtrack(path, counter):
        if len(path) == len(s):
            result.append(''.join(path))
            return
        for ch in counter:
            if counter[ch] > 0:
                path.append(ch)
                counter[ch] -= 1
                backtrack(path, counter)
                counter[ch] += 1
                path.pop()
    from collections import Counter
    result = []
    counter = Counter(s)
    backtrack([], counter)
    return result


