def next_smallest_palindrome(n):
    n = int(n)
    if n < 0:
        return 0
    s = str(n)
    length = len(s)

    def is_palindrome(x):
        sx = str(x)
        return sx == sx[::-1]
    half_len = (length + 1) // 2
    left_half = s[:half_len]

    def build_palindrome(left, length):
        if length % 2 == 0:
            return int(left + left[::-1])
        else:
            return int(left + left[:-1][::-1])
    pal = build_palindrome(left_half, length)
    if pal > n:
        return pal
    left_num = int(left_half)
    left_num += 1
    left_half_new = str(left_num)
    if len(left_half_new) > len(left_half):
        return 10 ** length + 1
    pal = build_palindrome(left_half_new, length)
    return pal


