def find_solution(a, b, n):

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        gcd, x1, y1 = extended_gcd(y, x % y)
        return (gcd, y1, x1 - x // y * y1)
    a_int = int(a)
    b_int = int(b)
    n_int = int(n)
    gcd, x0, y0 = extended_gcd(a_int, b_int)
    if n_int % gcd != 0:
        return None
    k = n_int // gcd
    x = x0 * k
    y = y0 * k
    return (x, y)


