def smallest_missing(arr):
    """
    Find the smallest missing non-negative integer starting from 0 in a sorted array.

    The array can contain negative numbers, floats, and duplicates.
    Only non-negative integers present in the array count as "found".
    The function returns the smallest non-negative integer not in the array.

    Examples:
    smallest_missing([-2, -1, 0, 1, 3]) -> 2
    smallest_missing([0, 1, 2, 3]) -> 4
    smallest_missing([1.5, 2.0, 3]) -> 0
    smallest_missing([]) -> 0
    """
    expected = 0
    for x in arr:
        if isinstance(x, int) and x == expected:
            expected += 1
        elif isinstance(x, float) and x.is_integer() and (int(x) == expected):
            expected += 1
        elif x > expected:
            break
    return expected


