def find_Max(arr):
    if not arr:
        return None
    left, right = (0, len(arr) - 1)
    if arr[left] < arr[right]:
        return arr[right]
    while left < right:
        mid = (left + right) // 2
        if mid < len(arr) - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        if arr[mid] > arr[left]:
            left = mid + 1
        else:
            right = mid - 1
    return arr[left]


