def dif_Square(n):
    if n == 0:
        return True
    abs_n = abs(n)
    from math import isqrt
    limit = isqrt(abs_n)
    for x in range(1, limit + 1):
        if abs_n % x == 0:
            y = abs_n // x
            candidates = []
            if n > 0:
                candidates.append((x, y))
                candidates.append((-x, -y))
            else:
                candidates.append((x, -y))
                candidates.append((-x, y))
            for X, Y in candidates:
                if (X + Y) % 2 == 0 and (Y - X) % 2 == 0:
                    return True
    return False


