def next_smallest_palindrome(n):
    if n < 9:
        return n + 1
    s = str(n)
    length = len(s)
    half = length // 2
    if all((ch == '9' for ch in s)):
        return n + 2
    if length % 2 == 0:
        left = s[:half]
        middle = ''
        right = s[half:]
    else:
        left = s[:half]
        middle = s[half]
        right = s[half + 1:]
    if middle:
        pal_candidate = int(left + middle + left[::-1])
    else:
        pal_candidate = int(left + left[::-1])
    if pal_candidate > n:
        return pal_candidate
    if middle:
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)
        if len(left_middle_str) > len(left) + 1:
            return int('1' + '0' * (length - 1) + '1')
        left = left_middle_str[:-1]
        middle = left_middle_str[-1]
        pal_candidate = int(left + middle + left[::-1])
        return pal_candidate
    else:
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            return int('1' + '0' * (length - 1) + '1')
        pal_candidate = int(left_str + left_str[::-1])
        return pal_candidate


