def find_solution(a, b, n):
    if a == 0 and b == 0:
        if n == 0:
            return ('x = ', 0, ', y = ', 0)
        else:
            return 'No solution'
    if a == 0:
        if b == 0:
            return 'No solution'
        if n % b == 0:
            y = n // b
            if y >= 0:
                return ('x = ', 0, ', y = ', y)
        return 'No solution'
    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return ('x = ', x, ', y = ', 0)
        return 'No solution'

    def div_ceil(a, b):
        return -(-a // b) if b != 0 else None

    def div_floor(a, b):
        return a // b if b != 0 else None
    if b > 0:
        if a > 0:
            x_start = 0
            x_end = n // a
        elif a < 0:
            x_start = max(0, div_ceil(n, a))
            x_end = 10 ** 9
        else:
            x_start = 0
            x_end = 0
    elif a > 0:
        x_start = max(0, div_ceil(n, a))
        x_end = 10 ** 9
    elif a < 0:
        x_start = 0
        x_end = max(0, n // a)
    else:
        x_start = 0
        x_end = 0
    max_iter = 10 ** 6
    if x_end > max_iter:
        x_end = max_iter
    for x in range(x_start, x_end + 1):
        remainder = n - a * x
        if b == 0:
            if remainder == 0 and x >= 0:
                return ('x = ', x, ', y = ', 0)
            continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return 'No solution'


