def get_total_number_of_sequences(m, n):
    if n == 1:
        return m
    dp_prev = [1] * (m + 1)
    for length in range(2, n + 1):
        dp_curr = [0] * (m + 1)
        for x in range(1, m + 1):
            limit = x // 2
            if limit >= 1:
                dp_curr[x] = sum(dp_prev[1:limit + 1])
            else:
                dp_curr[x] = 0
        dp_prev = dp_curr
    return sum(dp_prev[1:m + 1])


