def find_Max(seq):
    if not seq:
        return None
    left, right = (0, len(seq) - 1)
    if seq[left] < seq[right]:
        return seq[right]
    while left < right:
        mid = (left + right) // 2
        if seq[mid] > seq[right]:
            left = mid + 1
        else:
            right = mid
    return seq[left - 1]


