def lucky_num(n):
    if n <= 0:
        return []
    numbers = list(range(1, 2 * n * n))
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
    return numbers[:n]


