def next_smallest_palindrome(num):
    s = str(int(num))
    length = len(s)
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (length - 1) + '1')

    def is_palindrome(x):
        return x == x[::-1]

    def increment_str_num(x):
        return str(int(x) + 1)

    def make_palindrome(left, length):
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[-2::-1]
    half_len = (length + 1) // 2
    left = s[:half_len]
    palindrome = make_palindrome(left, length)
    if int(palindrome) > int(s):
        return int(palindrome)
    else:
        incremented_left = str(int(left) + 1)
        if len(incremented_left) > len(left):
            return int('1' + '0' * (length - 1) + '1')
        else:
            palindrome = make_palindrome(incremented_left, length)
            return int(palindrome)


