def find_solution(a, b, n):
    try:
        a = int(a)
        b = int(b)
        n = int(n)
    except:
        pass
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else 'No solution'
    if a == 0:
        if b != 0 and n % b == 0:
            return (0, n // b)
        else:
            return 'No solution'
    if b == 0:
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return 'No solution'
    from math import gcd
    g = gcd(a, b)
    if n % g != 0:
        return 'No solution'
    limit = abs(b) * abs(g) + 1
    for x in range(limit):
        diff = n - a * x
        if diff % b == 0:
            y = diff // b
            if x >= 0:
                return (x, y)
    return 'No solution'


