def permute_string(s):

    def backtrack(path, counter, length, result):
        if len(path) == length:
            result.append(''.join(path))
            return
        for ch in counter:
            if counter[ch] > 0:
                counter[ch] -= 1
                path.append(ch)
                backtrack(path, counter, length, result)
                path.pop()
                counter[ch] += 1
    counter = {}
    for ch in s:
        counter[ch] = counter.get(ch, 0) + 1
    result = []
    backtrack([], counter, len(s), result)
    return result


