def find_Max(arr, low, high):
    if low > high:
        return None
    if low == high:
        return arr[low]
    if arr[low] < arr[high]:
        return arr[high]
    mid = (low + high) // 2
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    if arr[low] == arr[mid] == arr[high]:
        left_max = find_Max(arr, low, mid - 1)
        right_max = find_Max(arr, mid + 1, high)
        candidates = [x for x in (left_max, right_max, arr[mid]) if x is not None]
        return max(candidates) if candidates else None
    if arr[mid] > arr[low]:
        return find_Max(arr, mid + 1, high)
    elif arr[mid] < arr[low]:
        return find_Max(arr, low, mid - 1)
    else:
        return find_Max(arr, low + 1, high)


